import sys, json, ast, re, tomllib

# THE SYNTAX HOOK OF A FILE SPACE (GH #901, S-27-2). `./write` hands every new
# text version here on `in_check` before it lands, unless the write carries
# `force` (then it never asks). This cell only judges: it answers `checked`
# with `hook` `ok` / `none` / `failed`, the language and, on `failed`, where
# the parser stopped. Building the `syntax` refusal is `./write`'s job.
#
# Pure and deterministic: the same body gives the same answer; no store, no
# state, no environment, no network, no file. Every parser is one of the
# Python standard library, and none of them runs the content (`ast.parse`
# compiles nothing and executes nothing).

# 1 MiB, not 4: near 4 MiB a parse took up to 9.66 s (Python, one short line
# per statement, host load 15), right at `external_timeout_ms`; a script
# timeout never answers `checked`. At 1 MiB the worst case measured 2.5 s.
MAX_CHECK_BYTES = 1024 * 1024

TOML_AT = re.compile(r"\s*\((?:at line (\d+), column (\d+)|at end of document)\)\s*$")


def _end_of(text):
    """Line and column (both 1-based) just past the last character."""
    last = text.rsplit("\n", 1)[-1]
    return text.count("\n") + 1, len(last) + 1


def check_json(text):
    """None when `text` is valid JSON, else {message, line, col}. The empty
    file (also one of whitespace only) is valid: a new, empty file is not a
    syntax error. Line and column come from the exception unchanged (1-based)."""
    if not text.strip():
        return None
    try:
        json.loads(text)
    except json.JSONDecodeError as e:
        return {"message": e.msg, "line": e.lineno, "col": e.colno}
    return None


def check_toml(text):
    """None when `text` is valid TOML, else {message, line, col}. `tomllib`
    of Python 3.12 carries the place only inside its message -- `(at line L,
    column C)` or `(at end of document)` -- so it is read from there and cut
    off the message."""
    try:
        tomllib.loads(text)
    except tomllib.TOMLDecodeError as e:
        msg = str(e)
        m = TOML_AT.search(msg)
        if m is None:
            return {"message": msg, "line": 0, "col": 0}
        if m.group(1):
            line, col = int(m.group(1)), int(m.group(2))
        else:
            line, col = _end_of(text)
        return {"message": msg[:m.start()], "line": line, "col": col}
    return None


def check_python(text):
    """None when `text` parses as Python, else {message, line, col}; a
    `TabError` or an `IndentationError` is a `SyntaxError` and fails too.
    `offset` is 1-based like the line; a place the parser does not name is 0."""
    try:
        ast.parse(text)
    except SyntaxError as e:
        return {"message": str(e.msg), "line": e.lineno or 0, "col": e.offset or 0}
    return None


# THE REGISTER -- the one place a language is named (Bau C hangs Rust and the
# others in here). Per language: the file endings (compared lower-case), the
# MIME types (compared lower-case, without parameters) and the checker. A
# registered MIME type wins over the ending; Markdown and plain text have no
# entry, because no parser would ever refuse them.
HOOKS = {
    "json": {"ext": [".json"], "mime": ["application/json"], "check": check_json},
    "toml": {"ext": [".toml"], "mime": ["application/toml"], "check": check_toml},
    "python": {"ext": [".py"], "mime": ["text/x-python"], "check": check_python},
}


def resolve(path, mime):
    """The language of a file by its MIME type first, then by its ending; ''
    when the register knows neither."""
    m = str(mime or "").split(";", 1)[0].strip().lower()
    if m:
        for lang, h in HOOKS.items():
            if m in h["mime"]:
                return lang
    name = str(path or "").rsplit("/", 1)[-1].lower()
    for lang, h in HOOKS.items():
        for ext in h["ext"]:
            if name.endswith(ext):
                return lang
    return ""


def verdict(body, max_bytes):
    """The answer body for one `in_check` body {path, mime, kind, text}."""
    body = body if isinstance(body, dict) else {}
    if body.get("kind") != "text":
        return {"hook": "none", "lang": ""}
    lang = resolve(body.get("path"), body.get("mime"))
    if not lang:
        return {"hook": "none", "lang": ""}
    text = body.get("text")
    if not isinstance(text, str):
        return {"hook": "none", "lang": lang, "note": "no_text"}
    if len(text.encode("utf-8", "surrogatepass")) > max_bytes:
        return {"hook": "none", "lang": lang, "note": "too_large_to_check"}
    try:
        err = HOOKS[lang]["check"](text)
    except (RecursionError, MemoryError):
        # A nesting deeper than the interpreter's stack is not proven wrong;
        # the hook steps aside instead of refusing a file it could not read.
        return {"hook": "none", "lang": lang, "note": "too_deep_to_check"}
    if err is None:
        return {"hook": "ok", "lang": lang}
    return {"hook": "failed", "lang": lang, "error": err}


def max_check_bytes(params):
    try:
        n = int((params or {}).get("max_check_bytes") or MAX_CHECK_BYTES)
    except (TypeError, ValueError):
        n = MAX_CHECK_BYTES
    return n if n > 0 else MAX_CHECK_BYTES


doc = json.load(sys.stdin)
hop = ((doc.get("envelope") or {}).get("header") or {}).get("hop") or {}
out = verdict(doc.get("body"), max_check_bytes(doc.get("params")))
out["header"] = {"route": "checked", "op_id": str(hop.get("op_id") or "")}
sys.stdout.write(json.dumps(out))
